package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.Feature;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class UTF8JsonGenerator_writeNumber_TriageGen2Test {

    private ByteArrayOutputStream out;
    private IOContext ioc;
    private ObjectCodec codec;

    // Constants to simulate internal state if possible, 
    // but since we are testing the class itself, we use the constructor.
    // Note: _cfgNumbersAsStrings and _features are internal fields.
    // In a real Jackson environment, these are set via JsonFactory.

    @Before
    public void setUp() {
        out = new ByteArrayOutputStream();
        ioc = IOContext.bootstrap();
        codec = null; // Not used in this specific method logic
    }

    /**
     * Helper to create a generator with specific features.
     * Since we cannot easily set private fields like _cfgNumbersAsStrings 
     * without reflection, we assume standard behavior or use a subclass/mock if needed.
     * However, for a professional unit test, we test the logic branches via the public API.
     */
    private UTF8JsonGenerator createGenerator(int features) throws IOException {
        return new UTF8JsonGenerator(ioc, features, codec, out);
    }

    @Test
    public void testWriteNumber_NullValue() throws IOException {
        UTF8JsonGenerator gen = createGenerator(0);
        gen.writeNumber((BigDecimal) null);
        // _writeNull() typically writes "null"
        assertEquals("null", out.toString());
    }

    @Test
    public void testWriteNumber_StandardBigDecimal_NoPlain_NoAsString() throws IOException {
        // Features: 0 (No WRITE_BIGDECIMAL_AS_PLAIN)
        // _cfgNumbersAsStrings: false (default)
        UTF8JsonGenerator gen = createGenerator(0);
        BigDecimal value = new BigDecimal("123.456E+2"); 
        // toString() for 123.456E+2 is "1.23456E+3"

        gen.writeNumber(value);

        String result = out.toString();
        // Since _cfgNumbersAsStrings is false and feature is disabled, it calls writeRaw(_asString(value))
        // which usually results in the standard toString() representation.
        assertEquals(value.toString(), result);
    }

    @Test
    public void testWriteNumber_StandardBigDecimal_WithPlainFeature() throws IOException {
        // Enable WRITE_BIGDECIMAL_AS_PLAIN
        int features = Feature.WRITE_BIGDECIMAL_AS_PLAIN.mappedFeatureId();
        UTF8JsonGenerator gen = createGenerator(features);

        BigDecimal value = new BigDecimal("123.456E+2");
        // toPlainString() for 123.456E+2 is "12345.6"

        gen.writeNumber(value);

        assertEquals(value.toPlainString(), out.toString());
    }

    /**
     * To test the _cfgNumbersAsStrings branch, we would need to control 
     * the internal boolean. Since it's private, we use reflection to ensure coverage.
     */
    @Test
    public void testWriteNumber_AsStrings_WithPlainFeature() throws IOException throws Exception {
        UTF8JsonGenerator gen = createGenerator(Feature.WRITE_BIGDECIMAL_AS_PLAIN.mappedFeatureId());

        // Use reflection to set _cfgNumbersAsStrings = true
        java.lang.reflect.Field field = UTF8JsonGenerator.class.getDeclaredField("_cfgNumbersAsStrings");
        field.setAccessible(true);
        field.set(gen, true);

        BigDecimal value = new BigDecimal("123.456E+2");
        gen.writeNumber(value);

        // Should call _writeQuotedRaw(value.toPlainString())
        // Result should be "12345.6" wrapped in quotes
        assertEquals("\"12345.6\"", out.toString());
    }

    @Test
    public void testWriteNumber_AsStrings_WithoutPlainFeature() throws IOException, Exception {
        UTF8JsonGenerator gen = createGenerator(0);

        java.lang.reflect.Field field = UTF8JsonGenerator.class.getDeclaredField("_cfgNumbersAsStrings");
        field.setAccessible(true);
        field.set(gen, true);

        BigDecimal value = new BigDecimal("123.456E+2");
        gen.writeNumber(value);

        // Should call _writeQuotedRaw(value.toString())
        assertEquals("\"" + value.toString() + "\"", out.toString());
    }

    @Test
    public void testWriteNumber_AsStrings_WithPlainFeature_AlternativeBranch() throws IOException, Exception {
        // This tests the specific branch: else if (_cfgNumbersAsStrings) { ... value.toPlainString() ... }
        // We already tested that above.
        // Let's ensure we cover the logic where _cfgNumbersAsStrings is false but Feature is enabled.

        int features = Feature.WRITE_BIGDECIMAL_AS_PLAIN.mappedFeatureId();
        UTF8JsonGenerator gen = createGenerator(features);

        java.lang.reflect.Field field = UTF8JsonGenerator.class.getDeclaredField("_cfgNumbersAsStrings");
        field.setAccessible(true);
        field.set(gen, false);

        BigDecimal value = new BigDecimal("123.456E+2");
        gen.writeNumber(value);

        // Since _cfgNumbersAsStrings is false, it goes to: 
        // else if (Feature.WRITE_BIGDECIMAL_AS_PLAIN.enabledIn(_features)) { writeRaw(value.toPlainString()); }
        assertEquals(value.toPlainString(), out.toString());
    }
}
